package com.xpertsedge.lms.learning;

import com.xpertsedge.lms.auth.IdentityService;
import com.xpertsedge.lms.common.ApiException;
import com.xpertsedge.lms.domain.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.*;
import tools.jackson.databind.json.JsonMapper;
import java.util.*;
import java.time.*;

@RestController @RequestMapping("/api/workspace/learning")
public class LearningController {
    private final JdbcTemplate db;
    private final IdentityService identities;
    private final CourseAccess access;
    private final CourseRepository courses;
    private final UserRepository users;
    private final Clock clock;
    private final JsonMapper json=JsonMapper.builder().build();
    public LearningController(JdbcTemplate db,IdentityService identities,CourseAccess access,CourseRepository courses,UserRepository users,Clock clock){this.db=db;this.identities=identities;this.access=access;this.courses=courses;this.users=users;this.clock=clock;}
    private ApiException bad(String message){return new ApiException(HttpStatus.BAD_REQUEST,message);}
    private UUID uuid(Object id){return UUID.fromString(id.toString());}
    private Map<String,Object> one(String sql,Object... params){return db.queryForList(sql,params).stream().findFirst().orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Learning record not found."));}
    private List<Map<String,Object>> visible(String table,AppUser u){return db.queryForList("SELECT * FROM "+table).stream().filter(r->access.read(u,r.get("course_id").toString())&&(u.getRole()!=Role.STUDENT||Boolean.TRUE.equals(r.get("published")))).toList();}
    public record LessonInput(@NotBlank @Size(max=60)String courseId,@NotBlank @Size(max=150)String title,@NotBlank @Size(max=12000)String body,@Min(0)int position,boolean published){}
    @GetMapping("/lessons") public List<?> lessons(Authentication auth){AppUser u=identities.current(auth);return visible("learning_lessons",u).stream().sorted(Comparator.comparingInt(r->((Number)r.get("position_index")).intValue())).map(row->{Map<String,Object> result=new LinkedHashMap<>(row);if(u.getRole()==Role.STUDENT)result.put("completed",db.queryForObject("SELECT COUNT(*) FROM lesson_completions WHERE lesson_id=? AND student_id=?",Integer.class,row.get("id"),u.getId())>0);return result;}).toList();}
    @PostMapping("/lessons") @Transactional public Map<String,Object> lesson(@Valid @RequestBody LessonInput r,Authentication auth){return saveLesson(UUID.randomUUID(),r,identities.current(auth),false);}
    @PutMapping("/lessons/{id}") @Transactional public Map<String,Object> lesson(@PathVariable UUID id,@Valid @RequestBody LessonInput r,Authentication auth){return saveLesson(id,r,identities.current(auth),true);}
    private Map<String,Object> saveLesson(UUID id,LessonInput r,AppUser u,boolean update){access.teach(u,r.courseId());if(update){var old=one("SELECT * FROM learning_lessons WHERE id=?",id);access.teach(u,old.get("course_id").toString());if(!r.courseId().equals(old.get("course_id")))throw bad("A lesson course cannot be changed.");db.update("UPDATE learning_lessons SET title=?,body=?,position_index=?,published=? WHERE id=?",r.title().strip(),r.body().strip(),r.position(),r.published(),id);}else db.update("INSERT INTO learning_lessons(id,course_id,title,body,position_index,published) VALUES(?,?,?,?,?,?)",id,r.courseId(),r.title().strip(),r.body().strip(),r.position(),r.published());return Map.of("id",id);}
    @PostMapping("/lessons/{id}/complete") @Transactional public Map<String,Object> complete(@PathVariable UUID id,Authentication auth){AppUser u=identities.current(auth);var lesson=one("SELECT * FROM learning_lessons WHERE id=?",id);access.require(u.getRole()==Role.STUDENT&&Boolean.TRUE.equals(lesson.get("published"))&&access.enrolled(u,lesson.get("course_id").toString()));if(db.queryForObject("SELECT COUNT(*) FROM lesson_completions WHERE lesson_id=? AND student_id=?",Integer.class,id,u.getId())==0)db.update("INSERT INTO lesson_completions(lesson_id,student_id,completed_at) VALUES(?,?,?)",id,u.getId(),OffsetDateTime.now(clock));return Map.of("completed",true);}
    public record QuestionInput(@NotBlank @Size(max=2000)String prompt,@NotNull @Size(min=2,max=6)List<@NotBlank @Size(max=500)String> options,@Min(0)int answerIndex){}
    public record QuizInput(@NotBlank @Size(max=60)String courseId,@NotBlank @Size(max=150)String title,@Min(1) @Max(100)int passMark,@Min(1) @Max(10)int maxAttempts,boolean published,@NotNull @Size(min=1,max=50)List<@Valid QuestionInput> questions){}
    private List<Map<String,Object>> questions(UUID id,boolean includeAnswers){return db.queryForList("SELECT * FROM quiz_questions WHERE quiz_id=? ORDER BY position_index",id).stream().map(q->{Map<String,Object> row=new LinkedHashMap<>();row.put("id",q.get("id"));row.put("prompt",q.get("prompt"));row.put("options",json.readValue(q.get("options_json").toString(),List.class));if(includeAnswers)row.put("answerIndex",q.get("answer_index"));return row;}).toList();}
    @GetMapping("/quizzes") public List<?> quizzes(Authentication auth){AppUser u=identities.current(auth);return visible("learning_quizzes",u).stream().map(q->{Map<String,Object> row=new LinkedHashMap<>(q);row.put("questions",questions(uuid(q.get("id")),u.getRole()!=Role.STUDENT));if(u.getRole()==Role.STUDENT)row.put("attemptsUsed",db.queryForObject("SELECT COUNT(*) FROM quiz_attempts WHERE quiz_id=? AND student_id=?",Integer.class,q.get("id"),u.getId()));return row;}).toList();}
    @PostMapping("/quizzes") @Transactional public Map<String,Object> quiz(@Valid @RequestBody QuizInput r,Authentication auth){return saveQuiz(UUID.randomUUID(),r,identities.current(auth),false);}
    @PutMapping("/quizzes/{id}") @Transactional public Map<String,Object> quiz(@PathVariable UUID id,@Valid @RequestBody QuizInput r,Authentication auth){return saveQuiz(id,r,identities.current(auth),true);}
    private Map<String,Object> saveQuiz(UUID id,QuizInput r,AppUser u,boolean update){access.teach(u,r.courseId());for(var q:r.questions())if(q.answerIndex()>=q.options().size())throw bad("Choose an answer from the question options.");if(update){var old=one("SELECT * FROM learning_quizzes WHERE id=? FOR UPDATE",id);access.teach(u,old.get("course_id").toString());if(!r.courseId().equals(old.get("course_id")))throw bad("A quiz course cannot be changed.");if(db.queryForObject("SELECT COUNT(*) FROM quiz_attempts WHERE quiz_id=?",Integer.class,id)>0)throw bad("Attempted quizzes are locked. Create a new quiz or change visibility.");db.update("UPDATE learning_quizzes SET title=?,pass_mark=?,max_attempts=?,published=? WHERE id=?",r.title().strip(),r.passMark(),r.maxAttempts(),r.published(),id);db.update("DELETE FROM quiz_questions WHERE quiz_id=?",id);}else db.update("INSERT INTO learning_quizzes(id,course_id,title,pass_mark,max_attempts,published) VALUES(?,?,?,?,?,?)",id,r.courseId(),r.title().strip(),r.passMark(),r.maxAttempts(),r.published());int pos=0;for(var q:r.questions())db.update("INSERT INTO quiz_questions(id,quiz_id,position_index,prompt,options_json,answer_index) VALUES(?,?,?,?,?,?)",UUID.randomUUID(),id,pos++,q.prompt().strip(),json.writeValueAsString(q.options()),q.answerIndex());return Map.of("id",id);}
    public record Visibility(boolean published){}
    @PutMapping("/quizzes/{id}/visibility") @Transactional public Map<String,Object> visibility(@PathVariable UUID id,@RequestBody Visibility r,Authentication auth){var q=one("SELECT * FROM learning_quizzes WHERE id=? FOR UPDATE",id);access.teach(identities.current(auth),q.get("course_id").toString());db.update("UPDATE learning_quizzes SET published=? WHERE id=?",r.published(),id);return Map.of("saved",true);}
    public record Answers(@NotNull @Size(min=1,max=50)List<@NotNull @Min(0)Integer> answers){}
    @PostMapping("/quizzes/{id}/attempts") @Transactional public Map<String,Object> attempt(@PathVariable UUID id,@Valid @RequestBody Answers r,Authentication auth){AppUser u=identities.current(auth);var q=one("SELECT * FROM learning_quizzes WHERE id=? FOR UPDATE",id);access.require(u.getRole()==Role.STUDENT&&Boolean.TRUE.equals(q.get("published"))&&access.enrolled(u,q.get("course_id").toString()));int used=db.queryForObject("SELECT COUNT(*) FROM quiz_attempts WHERE quiz_id=? AND student_id=?",Integer.class,id,u.getId());if(used>=((Number)q.get("max_attempts")).intValue())throw new ApiException(HttpStatus.CONFLICT,"Quiz attempt limit reached.");var questions=questions(id,true);if(r.answers().size()!=questions.size())throw bad("Answer every question.");int correct=0;for(int i=0;i<questions.size();i++){var question=questions.get(i);if(r.answers().get(i)>=((List<?>)question.get("options")).size())throw bad("Invalid answer option.");if(r.answers().get(i).intValue()==((Number)question.get("answerIndex")).intValue())correct++;}int score=(int)Math.round(100.0*correct/questions.size());boolean passed=score>=((Number)q.get("pass_mark")).intValue();UUID attempt=UUID.randomUUID();db.update("INSERT INTO quiz_attempts(id,quiz_id,student_id,answers_json,score,passed,submitted_at) VALUES(?,?,?,?,?,?,?)",attempt,id,u.getId(),json.writeValueAsString(r.answers()),score,passed,OffsetDateTime.now(clock));return Map.of("id",attempt,"score",score,"passed",passed,"attemptsUsed",used+1);}
    @GetMapping("/attempts") public List<?> attempts(Authentication auth){AppUser u=identities.current(auth);return db.queryForList("SELECT a.id,a.quiz_id,a.student_id,a.score,a.passed,a.submitted_at,q.course_id,q.title FROM quiz_attempts a JOIN learning_quizzes q ON q.id=a.quiz_id").stream().filter(r->access.read(u,r.get("course_id").toString())&&(u.getRole()!=Role.STUDENT||u.getId().equals(uuid(r.get("student_id"))))).toList();}
    private Map<String,Object> progress(AppUser student,Course course){String id=course.getId();int total=db.queryForObject("SELECT COUNT(*) FROM learning_lessons WHERE course_id=? AND published=TRUE",Integer.class,id);int completed=db.queryForObject("SELECT COUNT(*) FROM lesson_completions x JOIN learning_lessons l ON l.id=x.lesson_id WHERE l.course_id=? AND l.published=TRUE AND x.student_id=?",Integer.class,id,student.getId());var quizzes=db.queryForList("SELECT id FROM learning_quizzes WHERE course_id=? AND published=TRUE",id);long passed=quizzes.stream().filter(q->db.queryForObject("SELECT COUNT(*) FROM quiz_attempts WHERE quiz_id=? AND student_id=? AND passed=TRUE",Integer.class,q.get("id"),student.getId())>0).count();int pending=db.queryForObject("SELECT COUNT(*) FROM teaching_assignments a WHERE a.course_id=? AND NOT EXISTS (SELECT 1 FROM assignment_submissions s WHERE s.assignment_id=a.id AND s.student_id=? AND s.grade>=50)",Integer.class,id,student.getId());return Map.of("studentId",student.getId(),"studentName",student.getName(),"courseId",id,"courseName",course.getName(),"lessons",total,"completed",completed,"percent",total==0?0:(int)Math.round(100.0*completed/total),"quizzes",quizzes.size(),"passedQuizzes",passed,"eligible",access.enrolled(student,id)&&total>0&&completed==total&&!quizzes.isEmpty()&&passed==quizzes.size()&&pending==0);}
    @GetMapping("/progress") public List<?> progress(Authentication auth){AppUser u=identities.current(auth);List<Map<String,Object>> result=new ArrayList<>();for(Course course:courses.findAll()){if(!access.read(u,course.getId()))continue;if(u.getRole()==Role.STUDENT)result.add(progress(u,course));else for(AppUser student:users.findAll())if(access.enrolled(student,course.getId()))result.add(progress(student,course));}return result;}
    public record IssueInput(@NotNull UUID studentId,@NotBlank @Size(max=60)String courseId){}
    @GetMapping("/certificates") public List<?> certificates(Authentication auth){AppUser u=identities.current(auth);return db.queryForList("SELECT * FROM completion_certificates ORDER BY issued_at DESC").stream().filter(c->u.getRole()==Role.ADMIN||(u.getRole()==Role.STUDENT?u.getId().equals(uuid(c.get("student_id"))):access.read(u,c.get("course_id").toString()))).toList();}
    @PostMapping("/certificates") @Transactional public Map<String,Object> issue(@Valid @RequestBody IssueInput r,Authentication auth){AppUser u=identities.current(auth);access.require(u.getRole()==Role.ADMIN);AppUser student=users.findById(r.studentId()).orElseThrow(()->bad("Student not found."));Course course=courses.findById(r.courseId()).orElseThrow(()->bad("Course not found."));if(!Boolean.TRUE.equals(progress(student,course).get("eligible")))throw bad("Complete all published lessons, pass all published quizzes and score at least 50 on each assignment first.");UUID id=UUID.randomUUID();String code="XE-"+UUID.randomUUID().toString().toUpperCase(Locale.ROOT);db.update("INSERT INTO completion_certificates(id,code,course_id,student_id,student_name,course_name,issued_by,issued_at,revoked) VALUES(?,?,?,?,?,?,?,?,FALSE)",id,code,r.courseId(),r.studentId(),student.getName(),course.getName(),u.getId(),OffsetDateTime.now(clock));return Map.of("id",id,"code",code);}
    public record RevokeInput(boolean revoked){}
    @PutMapping("/certificates/{id}") @Transactional public Map<String,Object> revoke(@PathVariable UUID id,@RequestBody RevokeInput r,Authentication auth){access.require(identities.current(auth).getRole()==Role.ADMIN);one("SELECT * FROM completion_certificates WHERE id=?",id);db.update("UPDATE completion_certificates SET revoked=? WHERE id=?",r.revoked(),id);return Map.of("saved",true);}
}
